// Percent-encoding helpers mirroring Python's urllib.parse behavior.
// Always-safe characters (never quoted by Python's quote): letters, digits,
// and "_.-~". Additional safe characters are supplied per call site.

const ALWAYS_SAFE = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_.-~';

function hexByte(b) {
  return '%' + b.toString(16).toUpperCase().padStart(2, '0');
}

// Equivalent of Python's urllib.parse.quote(s, safe=safe): UTF-8 percent
// encoding with uppercase hex digits.
export function quote(str, safe = '') {
  const safeSet = new Set([...(ALWAYS_SAFE + safe)]);
  let out = '';
  for (const ch of str) {
    if (safeSet.has(ch)) {
      out += ch;
    } else {
      for (const b of Buffer.from(ch, 'utf8')) {
        out += hexByte(b);
      }
    }
  }
  return out;
}

// Equivalent of Python's urllib.parse.quote_plus: quote, then spaces become '+'.
export function quotePlus(str, safe = '') {
  return quote(str, safe).replace(/%20/g, '+');
}

// Equivalent of Python's urllib.parse.unquote with errors='replace':
// valid %XX escapes are decoded as UTF-8, anything else is left untouched.
export function unquote(str) {
  let out = '';
  let i = 0;
  while (i < str.length) {
    const ch = str[i];
    if (ch === '%' && /^[0-9A-Fa-f]{2}$/.test(str.slice(i + 1, i + 3))) {
      const bytes = [];
      while (i < str.length && str[i] === '%' && /^[0-9A-Fa-f]{2}$/.test(str.slice(i + 1, i + 3))) {
        bytes.push(parseInt(str.slice(i + 1, i + 3), 16));
        i += 3;
      }
      out += new TextDecoder('utf-8', { fatal: false }).decode(Buffer.from(bytes));
    } else {
      out += ch;
      i += 1;
    }
  }
  return out;
}

// Equivalent of Python's urllib.parse.unquote_plus: '+' becomes ' ', then unquote.
export function unquotePlus(str) {
  return unquote(str.replace(/\+/g, ' '));
}

// IDNA (punycode) host conversion, backed by Node's built-in node:url.
import { domainToASCII, domainToUnicode } from 'node:url';

// Convert a Unicode host name to its ASCII (punycode) form, as furl does
// when composing the full URL. Non-domain hosts (e.g. IPv6 literals in
// brackets) are returned unchanged.
export function hostToASCII(host) {
  if (host === null || host === undefined || host === '') return host;
  if (host.startsWith('[')) return host; // IPv6 literal
  const ascii = domainToASCII(host);
  return ascii === '' ? host : ascii;
}

// Convert a host name to its Unicode form, as exposed by furl's `host`
// property.
export function hostToUnicode(host) {
  if (host === null || host === undefined || host === '') return host;
  if (host.startsWith('[')) return host; // IPv6 literal
  return domainToUnicode(host);
}

// Query string model mirroring furl's Query: an ordered list of
// (key, value, hasSeparator) pairs, form-encoded with quote_plus semantics.
import { quotePlus, unquotePlus } from './pycodec.mjs';

export class Query {
  constructor(pairs = []) {
    // Each pair: { key, value, hasEq }. `value` is null when the original
    // segment had no '=' (e.g. "?flag"), and is re-rendered as a bare key.
    this.pairs = pairs;
  }

  // Parse a raw query string like "a=1&flag&b=2" (no leading '?').
  static parse(raw) {
    const pairs = [];
    if (raw !== '') {
      for (const segment of raw.split('&')) {
        const idx = segment.indexOf('=');
        if (idx === -1) {
          pairs.push({ key: unquotePlus(segment), value: null, hasEq: false });
        } else {
          pairs.push({
            key: unquotePlus(segment.slice(0, idx)),
            value: unquotePlus(segment.slice(idx + 1)),
            hasEq: true,
          });
        }
      }
    }
    return new Query(pairs);
  }

  // Mirror of furl Query.add(): append new key/value pairs (in place) and
  // return the query object itself.
  add(params) {
    for (const [key, value] of Object.entries(params)) {
      this.pairs.push({ key: String(key), value: String(value), hasEq: true });
    }
    return this;
  }

  toString() {
    return this.pairs
      .map((p) => (p.hasEq ? `${quotePlus(p.key)}=${quotePlus(p.value)}` : quotePlus(p.key)))
      .join('&');
  }
}

// Minimal furl re-implementation: parses a URL string and exposes
// scheme / host / path / query / url with furl-compatible semantics.
import { quote } from './pycodec.mjs';
import { hostToASCII, hostToUnicode } from './idna.mjs';
import { Query } from './query.mjs';

// Safe characters observed for path segments: RFC 3986 pchar plus '/'
// (i.e. unreserved + sub-delims + ":@/"). Everything else, including '%',
// is percent-encoded.
const PATH_SAFE = "!$&'()*+,;=:@/";
// Fragment allows everything the path allows, plus '?'.
const FRAGMENT_SAFE = PATH_SAFE + '?';

// Default ports per scheme (empirically matching furl's behavior): a port
// equal to the scheme's default is omitted from the rendered URL.
const DEFAULT_PORTS = {
  ftp: 21,
  sftp: 22,
  ssh: 22,
  telnet: 23,
  gopher: 70,
  http: 80,
  ws: 80,
  nntp: 119,
  ldap: 389,
  https: 443,
  wss: 443,
  rtsp: 554,
};

const SCHEME_RE = /^([A-Za-z][A-Za-z0-9+.-]*):/;

export class InvalidPortError extends Error {
  constructor(rawPort) {
    super(`Invalid port '${rawPort}'.`);
    this.name = 'ValueError';
  }
}

function parsePort(raw) {
  if (raw === '') return null;
  if (!/^[0-9]+$/.test(raw)) throw new InvalidPortError(raw);
  const port = parseInt(raw, 10);
  if (port < 1 || port > 65535) throw new InvalidPortError(raw);
  return port;
}

export class Furl {
  constructor(url) {
    let rest = String(url);

    // Fragment: everything after the first '#'.
    this.fragment = null;
    const hashIdx = rest.indexOf('#');
    if (hashIdx !== -1) {
      this.fragment = rest.slice(hashIdx + 1);
      rest = rest.slice(0, hashIdx);
    }

    // Query: everything after the first '?'.
    let rawQuery = '';
    const qIdx = rest.indexOf('?');
    if (qIdx !== -1) {
      rawQuery = rest.slice(qIdx + 1);
      rest = rest.slice(0, qIdx);
    }
    this.query = Query.parse(rawQuery);

    // Scheme: "alpha *(alnum | '+' | '-' | '.')" followed by ':'.
    this.scheme = null;
    const m = rest.match(SCHEME_RE);
    if (m) {
      this.scheme = m[1].toLowerCase();
      rest = rest.slice(m[0].length);
    }

    // Network location: introduced by '//', runs until the next '/'.
    this.username = null;
    this.password = null;
    this.host = null;
    this.port = null;
    this.hasNetloc = false;
    if (rest.startsWith('//')) {
      this.hasNetloc = true;
      const slashIdx = rest.indexOf('/', 2);
      const authority = slashIdx === -1 ? rest.slice(2) : rest.slice(2, slashIdx);
      rest = slashIdx === -1 ? '' : rest.slice(slashIdx);

      let hostport = authority;
      const atIdx = authority.lastIndexOf('@');
      if (atIdx !== -1) {
        const userinfo = authority.slice(0, atIdx);
        hostport = authority.slice(atIdx + 1);
        const colonIdx = userinfo.indexOf(':');
        if (colonIdx === -1) {
          this.username = userinfo;
        } else {
          this.username = userinfo.slice(0, colonIdx);
          this.password = userinfo.slice(colonIdx + 1);
        }
      }

      if (hostport.startsWith('[')) {
        // IPv6 literal: [::1]:8080
        const end = hostport.indexOf(']');
        this.host = hostport.slice(0, end + 1).toLowerCase();
        const tail = hostport.slice(end + 1);
        if (tail.startsWith(':')) this.port = parsePort(tail.slice(1));
      } else {
        const colonIdx = hostport.lastIndexOf(':');
        if (colonIdx !== -1) {
          this.host = hostport.slice(0, colonIdx).toLowerCase();
          this.port = parsePort(hostport.slice(colonIdx + 1));
        } else {
          this.host = hostport.toLowerCase();
        }
      }
    }

    // Whatever remains is the path (kept raw, quoted on render).
    this.path = rest;
  }

  get pathstr() {
    return quote(this.path, PATH_SAFE);
  }

  get url() {
    let out = '';
    if (this.scheme !== null) out += this.scheme + ':';
    if (this.hasNetloc) {
      out += '//';
      if (this.username !== null) {
        out += this.username;
        if (this.password !== null) out += ':' + this.password;
        out += '@';
      }
      out += hostToASCII(this.host === null ? '' : this.host);
      const defaultPort = this.scheme === null ? undefined : DEFAULT_PORTS[this.scheme];
      if (this.port !== null && this.port !== defaultPort) out += ':' + this.port;
    }
    out += this.pathstr;
    const queryStr = this.query.toString();
    if (queryStr !== '') out += '?' + queryStr;
    if (this.fragment !== null) out += '#' + quote(this.fragment, FRAGMENT_SAFE);
    return out;
  }
}

export function furl(url) {
  return new Furl(url);
}

