// Minimal argparse clone covering the subset used by the original script:
// required string options ("--name value" and "--name=value" forms),
// -h/--help, and argparse-compatible error messages / exit codes.
import { basename } from 'node:path';

export class ArgumentParser {
  constructor() {
    // Program name mirrors Python argparse: basename of the script.
    this.prog = basename(process.argv[1] || '');
    this.options = []; // [{ name, metavar, required }]
  }

  add_argument(name, { required = false } = {}) {
    this.options.push({ name, metavar: name.slice(2).toUpperCase(), required });
  }

  usage() {
    const parts = [`usage: ${this.prog} [-h]`];
    for (const opt of this.options) {
      parts.push(opt.required ? `${opt.name} ${opt.metavar}` : `[${opt.name} ${opt.metavar}]`);
    }
    return parts.join(' ');
  }

  printHelp() {
    const lines = [this.usage(), '', 'options:', '  -h, --help  show this help message and exit'];
    for (const opt of this.options) {
      lines.push(`  ${opt.name} ${opt.metavar}`);
    }
    console.log(lines.join('\n'));
  }

  error(message) {
    console.error(this.usage());
    console.error(`${this.prog}: error: ${message}`);
    process.exit(2);
  }

  parse_args(argv = process.argv.slice(2)) {
    const values = {};
    for (const opt of this.options) values[opt.name.slice(2)] = undefined;

    const byName = new Map(this.options.map((o) => [o.name, o]));
    const extras = [];

    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];
      if (token === '-h' || token === '--help') {
        this.printHelp();
        process.exit(0);
      }
      if (token.startsWith('--') && token.length > 2) {
        const eqIdx = token.indexOf('=');
        const name = eqIdx === -1 ? token : token.slice(0, eqIdx);
        const opt = byName.get(name);
        if (!opt) {
          extras.push(token);
          continue;
        }
        let value;
        if (eqIdx !== -1) {
          value = token.slice(eqIdx + 1);
        } else {
          const next = argv[i + 1];
          // A following token is consumed as the value unless it looks like
          // another option (negative numbers and bare '-' are still values).
          const looksLikeOption =
            next !== undefined && next.length > 1 && next.startsWith('-') && !/^-\d/.test(next);
          if (next === undefined || looksLikeOption) {
            this.error(`argument ${name}: expected one argument`);
          }
          value = next;
          i += 1;
        }
        values[name.slice(2)] = value;
      } else {
        extras.push(token);
      }
    }

    const missing = this.options
      .filter((o) => o.required && values[o.name.slice(2)] === undefined)
      .map((o) => o.name);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return values;
  }
}

// Entry point — JS port of test6.py.
import { ArgumentParser } from './lib/argparse.mjs';
import { furl } from './lib/furl.mjs';

// Python prints None for null values; mirror that.
function pyStr(value) {
  return value === null || value === undefined ? 'None' : String(value);
}

function main() {
  const parser = new ArgumentParser();
  parser.add_argument('--a', { required: true });
  parser.add_argument('--b', { required: true });
  parser.add_argument('--c', { required: true });
  const args = parser.parse_args();

  const f = furl(args.a); // 创建furl对象，解析URL
  console.log(pyStr(f.scheme)); // 输出协议
  console.log(pyStr(f.host)); // 输出主机名
  console.log(f.pathstr); // 输出路径
  console.log(f.query.add({ [args.b]: args.c }).toString()); // 添加查询参数并输出
  console.log(f.url); // 输出完整URL
}

try {
  main();
} catch (err) {
  // Mirror the Python behavior of an unhandled ValueError (exit code 1).
  console.error(`${err.name}: ${err.message}`);
  process.exit(1);
}
